 fn eval(f:&F,p:&P,x:&N)->N {p.iter().rev().fold(n(0),|r,a|f.add(&f.mul(&r,x),a))}
 fn monic(f:&F,p:P)->P {if p.is_empty(){return p;}let inv=f.inv(p.last().unwrap());trim(p.iter().map(|a|f.mul(a,&inv)).collect())}
 fn gcd(f:&F,mut a:P,mut b:P)->P {while !b.is_empty(){let r=f.rem(a,&b,true);a=b;b=r;}monic(f,a)}
 fn div(f:&F,mut a:P,b:&P)->(P,P){assert!(!b.is_empty());if a.len()<b.len(){return(vec![],a);}let mut q=vec![n(0);a.len()-b.len()+1];let inv=f.inv(b.last().unwrap());while !a.is_empty()&&a.len()>=b.len(){let j=a.len()-b.len();let c=f.mul(a.last().unwrap(),&inv);q[j]=f.add(&q[j],&c);for(i,x)in b.iter().enumerate(){a[i+j]=f.sub(&a[i+j],&f.mul(&c,x));}a=trim(a);} (trim(q),a)}
 fn plus_const(f:&F,mut p:P,c:&N)->P{if p.is_empty(){p.push(n(0));}p[0]=f.add(&p[0],c);trim(p)}
