 fn sq(f:&F,r:&P,c:&[P;2])->P{let mut out=vec![n(0);5];for i in 0..5{let v=if i<r.len(){f.mul(&r[i],&r[i])}else{n(0)};if i<=2{out[2*i]=f.add(&out[2*i],&v);}else{for j in 0..5{out[j]=f.add(&out[j],&f.mul(&v,&c[i-3][j]));}}}trim(out)}
 fn betas(f:&F,basis:&[N])->Vec<N>{let mut v=basis.to_vec();let mut out=vec![];for i in 0..v.len(){let beta=v[i].clone();assert!(!beta.is_zero(),"dependent basis");for value in v.iter_mut().skip(i+1){*value=f.add(&f.mul(value,value),&f.mul(&beta,value));}out.push(beta);}out}
