 fn split(f:&F,g:P,level:usize,offset:N,basis:&[N],beta:&[N],remainders:&[P],roots:&mut Vec<N>,nodes:&mut usize){*nodes+=1;assert!(*nodes<=1000,"node cap");if g.len()<=1{return;}if g.len()==2{assert_eq!(g[1],n(1));roots.push(f.neg(&g[0]));return;}assert!(level>0,"nonlinear leaf");let i=level-1;let c=linear_eval(f,&offset,&beta[..i]);let left=gcd(f,g.clone(),plus_const(f,remainders[i].clone(),&c));let(right,rem)=div(f,g,&left);assert!(rem.is_empty());split(f,left,i,offset.clone(),basis,beta,remainders,roots,nodes);split(f,right,i,f.add(&offset,&basis[i]),basis,beta,remainders,roots,nodes);}
 fn solve(f:&F,h:&P,basis:&[N],offset:&N)->(Vec<(N,usize)>,usize){assert_eq!(f.characteristic(),2,"binary-domain implementation");assert!(basis.len()<=32);let beta=betas(f,basis);let cached=cache(f,h);let mut rs=vec![vec![n(0),n(1)]];for b in &beta{let r=rs.last().unwrap();let mut t=sq(f,r,&cached);if t.len()<r.len(){t.resize(r.len(),n(0));}for(i,x)in r.iter().enumerate(){t[i]=f.add(&t[i],&f.mul(b,x));}rs.push(trim(t));}let c=linear_eval(f,offset,&beta);let g=gcd(f,h.clone(),plus_const(f,rs.last().unwrap().clone(),&c));let mut roots=vec![];let mut nodes=0;split(f,g,basis.len(),offset.clone(),basis,&beta,&rs,&mut roots,&mut nodes);roots.sort();assert!(!roots.windows(2).any(|x|x[0]==x[1]));let mut remaining=h.clone();let mut output=vec![];for root in roots{assert!(eval(f,h,&root).is_zero());assert_eq!(linear_eval(f,&root,&beta),c);let mut multiplicity=0;loop{let(q,r)=div(f,remaining.clone(),&vec![f.neg(&root),n(1)]);if !r.is_empty(){break;}remaining=q;multiplicity+=1;}assert!(multiplicity>0);output.push((root,multiplicity));}assert!(nodes<=2*h.len()*basis.len()+1);(output,nodes)}
 fn brute(f:&F,h:&P,basis:&[N],offset:&N)->Vec<(N,usize)>{let mut d=vec![offset.clone()];for b in basis{let extra=d.iter().map(|a|f.add(a,b)).collect::<Vec<_>>();d.extend(extra);}d.sort();d.into_iter().filter(|x|eval(f,h,x).is_zero()).map(|x|{let mult=(1..h.len()).find(|k|{let p=trim((*k..h.len()).map(|i|if i&k==*k{h[i].clone()}else{n(0)}).collect());!eval(f,&p,&x).is_zero()}).unwrap();(x,mult)}).collect()}
